@interface DGOptionsAnimator:NSObject<UIViewControllerAnimatedTransitioning>
@property(nonatomic) BOOL presenting;
@end
@implementation DGOptionsAnimator
- (NSTimeInterval)transitionDuration:(id<UIViewControllerContextTransitioning>)context{return DGDuration(self.presenting?.38:.24);}
- (void)animateTransition:(id<UIViewControllerContextTransitioning>)context{
 DGOptions *controller=(DGOptions *)[context viewControllerForKey:self.presenting?UITransitionContextToViewControllerKey:UITransitionContextFromViewControllerKey];UIView *view=controller.view;if(self.presenting){view.frame=context.containerView.bounds;[context.containerView addSubview:view];[view setNeedsLayout];[view layoutIfNeeded];}UIView *panel=[controller transitionPanel];
 // Preserve the panel silhouette in both directions instead of scaling a page into a tiny screenshot.
 CGAffineTransform collapsed=CGAffineTransformMakeTranslation(0,36);if(self.presenting){panel.transform=collapsed;panel.alpha=0;}
 DGAnimate(self.presenting?.38:.24,^{panel.transform=self.presenting?CGAffineTransformIdentity:collapsed;panel.alpha=self.presenting?1:0;},^(BOOL done){BOOL complete=!context.transitionWasCancelled;if(!self.presenting&&complete)[view removeFromSuperview];panel.transform=CGAffineTransformIdentity;panel.alpha=1;[context completeTransition:complete];});
}
@end
static NSDictionary *Switch(NSString *title,NSString *key,NSString *detail,BOOL initial){return @{ @"type":@"switch",@"title":title,@"key":key,@"detail":detail,@"default":@(initial)};}
static NSDictionary *Range(NSString *title,NSString *key,double minimum,double maximum,double initial,double step,NSString *detail){return @{ @"type":@"range",@"title":title,@"key":key,@"detail":detail,@"min":@(minimum),@"max":@(maximum),@"default":@(initial),@"step":@(step)};}
static NSDictionary *Segments(NSString *title,NSString *key,NSArray *items,NSInteger initial,NSString *detail){return @{ @"type":@"segments",@"title":title,@"key":key,@"items":items,@"default":@(initial),@"detail":detail};}
static NSDictionary *Action(NSString *title,NSString *action,NSString *detail){return @{ @"type":@"action",@"title":title,@"action":action,@"detail":detail};}
