- (void)viewDidLayoutSubviews{[super viewDidLayoutSubviews];CGFloat h=self.view.bounds.size.height,panel=self.actions?MIN(h*.68,460):h*.82;_glass.bounds=CGRectMake(0,0,self.view.bounds.size.width,panel);_glass.center=CGPointMake(self.view.bounds.size.width/2,h-panel/2);_title.frame=CGRectMake(24,18,self.view.bounds.size.width-92,34);_close.frame=CGRectMake(self.view.bounds.size.width-62,12,44,44);_table.frame=CGRectMake(0,60,self.view.bounds.size.width,panel-60);_table.contentInset=UIEdgeInsetsMake(0,0,self.view.safeAreaInsets.bottom,0);}
- (void)viewDidDisappear:(BOOL)animated{[super viewDidDisappear:animated];[NSNotificationCenter.defaultCenter postNotificationName:@"DGResumePlayback" object:nil];}
- (void)close{[self dismissViewControllerAnimated:YES completion:nil];}
- (void)finish:(void (^)(UIViewController *host))action{UIViewController *host=self.presentingViewController;[self dismissViewControllerAnimated:YES completion:^{if(action)action(host);}];}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)tableView{return self.actions?1:[self rows].count;}
- (NSInteger)tableView:(UITableView *)tableView numberOfRowsInSection:(NSInteger)section{return self.actions?6:Array([self rows][section]).count;}
- (NSString *)tableView:(UITableView *)tableView titleForHeaderInSection:(NSInteger)section{return self.actions?nil:@[@"推荐过滤",@"弹幕",@"画面",@"播放",@"交互",@"外观",@"诊断日志",@"账号"][section];}
- (NSString *)rangeTitle:(NSDictionary *)row value:(double)value{NSString *key=row[@"key"];NSString *unit=[key isEqualToString:@"douglass.holdMaximum"]?@"×":@"";return [NSString stringWithFormat:@"%@ · %.1f%@",row[@"title"],value,unit];}
- (CGFloat)tableView:(UITableView *)tableView heightForRowAtIndexPath:(NSIndexPath *)path{if(self.actions)return 56;NSDictionary *row=[self rows][path.section][path.row];BOOL control=[@[@"range",@"segments"]containsObject:row[@"type"]];return control?([row[@"detail"]length]?125:96):[row[@"detail"]length]?78:56;}
- (UITableViewCell *)tableView:(UITableView *)tableView cellForRowAtIndexPath:(NSIndexPath *)path{
 if(self.actions){UITableViewCell *cell=[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleDefault reuseIdentifier:nil];cell.backgroundColor=[UIColor.systemBackgroundColor colorWithAlphaComponent:.44];BOOL photo=Array(self.work[@"images"]).count>0;cell.textLabel.text=@[photo?@"保存当前图片":@"保存视频",@"保存封面",@"保存音频",@"复制文案",@"复制分享链接",@"保存此帧画面"][path.row];cell.imageView.image=[UIImage systemImageNamed:@[photo?@"photo":@"video",@"photo.on.rectangle",@"music.note",@"doc.on.doc",@"square.and.arrow.up",@"camera.viewfinder"][path.row]];cell.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return cell;}
 NSDictionary *row=[self rows][path.section][path.row];NSString *type=row[@"type"],*key=row[@"key"];id saved=key?[NSUserDefaults.standardUserDefaults objectForKey:key]:nil;double value=[saved?:row[@"default"] doubleValue];
 if([type isEqualToString:@"range"]){UISlider *slider=[UISlider new];slider.accessibilityIdentifier=key;slider.minimumValue=[row[@"min"]floatValue];slider.maximumValue=[row[@"max"]floatValue];slider.value=value;[slider addTarget:self action:@selector(rangeChanged:) forControlEvents:UIControlEventValueChanged];return [[DGSettingControlCell alloc]initWithTitle:[self rangeTitle:row value:value] detail:row[@"detail"] control:slider];}
 if([type isEqualToString:@"segments"]){UISegmentedControl *segments=[[UISegmentedControl alloc]initWithItems:row[@"items"]];segments.accessibilityIdentifier=key;segments.selectedSegmentIndex=MIN((NSInteger)Array(row[@"items"]).count-1,MAX(0,(NSInteger)value));[segments addTarget:self action:@selector(segmentsChanged:) forControlEvents:UIControlEventValueChanged];return [[DGSettingControlCell alloc]initWithTitle:row[@"title"] detail:row[@"detail"] control:segments];}
 UITableViewCell *cell=[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:nil];cell.backgroundColor=[UIColor.systemBackgroundColor colorWithAlphaComponent:.44];cell.textLabel.text=row[@"title"];cell.textLabel.font=[UIFont systemFontOfSize:15];cell.detailTextLabel.text=row[@"detail"];cell.detailTextLabel.numberOfLines=2;cell.detailTextLabel.font=[UIFont systemFontOfSize:11];cell.detailTextLabel.textColor=UIColor.secondaryLabelColor;
 if([type isEqualToString:@"switch"]){UISwitch *toggle=[UISwitch new];toggle.accessibilityIdentifier=key;toggle.on=value!=0;if([key isEqualToString:@"douglass.pip"]&&![AVPictureInPictureController isPictureInPictureSupported]){toggle.enabled=NO;toggle.on=NO;cell.detailTextLabel.text=@"此设备不支持画中画";}if([key isEqualToString:@"douglass.force120"]){toggle.enabled=(self.view.window.windowScene.screen?:UIScreen.mainScreen).maximumFramesPerSecond>=120;cell.detailTextLabel.text=DGRefreshRateStatus();}[toggle addTarget:self action:@selector(toggleChanged:) forControlEvents:UIControlEventValueChanged];cell.accessoryView=toggle;cell.selectionStyle=UITableViewCellSelectionStyleNone;}else{cell.accessoryType=UITableViewCellAccessoryDisclosureIndicator;if([row[@"action"]isEqualToString:@"logout"])cell.textLabel.textColor=UIColor.systemRedColor;if([row[@"action"]isEqualToString:@"font"]){NSString *font=[NSUserDefaults.standardUserDefaults stringForKey:@"douglass.danmaku.fontName"];if(font.length)cell.detailTextLabel.text=font;}}return cell;
}
- (void)notifyKey:(NSString *)key{if([key isEqualToString:@"douglass.appearance"]){DGApplyAppearance();return;}if([key isEqualToString:@"douglass.diagnostics"]){DGDiagnosticEnable([NSUserDefaults.standardUserDefaults boolForKey:key]);return;}if([key isEqualToString:@"douglass.force120"]){DGRefreshRateApply();return;}NSString *notification=[key hasPrefix:@"douglass.filter."]?@"DGFiltersChanged":([key isEqualToString:@"douglass.quality"]||[key isEqualToString:@"douglass.highFPS"])?@"DGPlaybackQualityChanged":@"DouGlassSettingsChanged";[NSNotificationCenter.defaultCenter postNotificationName:notification object:nil];}
- (void)toggleChanged:(UISwitch *)control{NSString *key=control.accessibilityIdentifier;if([key isEqualToString:@"douglass.backgroundAudio"])DGHaptic();[NSUserDefaults.standardUserDefaults setBool:control.on forKey:key];[self notifyKey:key];if([key isEqualToString:@"douglass.force120"]){__weak DGOptions *weak=self;dispatch_after(dispatch_time(DISPATCH_TIME_NOW,1200*NSEC_PER_MSEC),dispatch_get_main_queue(),^{DGOptions *self=weak;if(self.view.window){NSIndexPath *path=[NSIndexPath indexPathForRow:1 inSection:4];UITableViewCell *cell=[self->_table cellForRowAtIndexPath:path];cell.detailTextLabel.text=DGRefreshRateStatus();}});}}
- (NSDictionary *)rowForControl:(UIView *)control{for(NSArray *section in [self rows])for(NSDictionary *row in section)if([row[@"key"]isEqualToString:control.accessibilityIdentifier])return row;return @{};}
- (void)rangeChanged:(UISlider *)control{NSDictionary *row=[self rowForControl:control];double step=[row[@"step"]doubleValue],value=round(control.value/step)*step;[NSUserDefaults.standardUserDefaults setDouble:value forKey:control.accessibilityIdentifier];for(UIView *view=control.superview;view;view=view.superview)if([view isKindOfClass:DGSettingControlCell.class]){((DGSettingControlCell *)view).heading.text=[self rangeTitle:row value:value];break;}[self notifyKey:control.accessibilityIdentifier];}
- (void)segmentsChanged:(UISegmentedControl *)control{NSString *key=control.accessibilityIdentifier;NSInteger selected=control.selectedSegmentIndex;[NSUserDefaults.standardUserDefaults setInteger:selected forKey:key];if([key isEqualToString:@"douglass.danmaku.color"])[NSUserDefaults.standardUserDefaults removeObjectForKey:@"douglass.danmaku.rgb"];if([key isEqualToString:@"douglass.danmaku.font"])[NSUserDefaults.standardUserDefaults removeObjectForKey:@"douglass.danmaku.fontName"];[self notifyKey:key];}
- (void)fontPickerViewControllerDidPickFont:(UIFontPickerViewController *)picker{UIFont *font=[UIFont fontWithDescriptor:picker.selectedFontDescriptor size:14];if(font.fontName.length)[NSUserDefaults.standardUserDefaults setObject:font.fontName forKey:@"douglass.danmaku.fontName"];[picker dismissViewControllerAnimated:YES completion:nil];[self notifyKey:@"douglass.danmaku.fontName"];[_table reloadData];}
- (void)fontPickerViewControllerDidCancel:(UIFontPickerViewController *)picker{[picker dismissViewControllerAnimated:YES completion:nil];}
- (void)documentPicker:(UIDocumentPickerViewController *)controller didPickDocumentsAtURLs:(NSArray<NSURL *> *)urls{NSURL *source=urls.firstObject;if(!source)return;BOOL scoped=[source startAccessingSecurityScopedResource];NSData *data=[NSData dataWithContentsOfURL:source];if(scoped)[source stopAccessingSecurityScopedResource];if(!data.length||data.length>30*1024*1024){DGToast(self,@"字体文件为空或超过 30MB");return;}NSURL *folder=[[NSFileManager.defaultManager URLsForDirectory:NSApplicationSupportDirectory inDomains:NSUserDomainMask].firstObject URLByAppendingPathComponent:@"Fonts" isDirectory:YES];[NSFileManager.defaultManager createDirectoryAtURL:folder withIntermediateDirectories:YES attributes:nil error:nil];NSURL *file=[folder URLByAppendingPathComponent:[NSUUID.UUID.UUIDString stringByAppendingPathExtension:source.pathExtension.lowercaseString]];[data writeToURL:file atomically:YES];CFArrayRef descriptors=CTFontManagerCreateFontDescriptorsFromURL((__bridge CFURLRef)file);NSArray *fonts=CFBridgingRelease(descriptors);if(!fonts.count){[NSFileManager.defaultManager removeItemAtURL:file error:nil];DGToast(self,@"文件不是可用字体");return;}CFErrorRef error=NULL;BOOL ok=CTFontManagerRegisterFontsForURL((__bridge CFURLRef)file,kCTFontManagerScopeProcess,&error);if(error)CFRelease(error);NSString *name=CFBridgingRelease(CTFontDescriptorCopyAttribute((__bridge CTFontDescriptorRef)fonts.firstObject,kCTFontNameAttribute));if(!ok||!name.length){DGToast(self,@"字体无法加载");return;}[NSUserDefaults.standardUserDefaults setObject:name forKey:@"douglass.danmaku.fontName"];[self notifyKey:@"douglass.danmaku.fontName"];[_table reloadData];DGToast(self,@"字体已导入");}
- (void)rgb{NSArray *saved=[NSUserDefaults.standardUserDefaults arrayForKey:@"douglass.danmaku.rgb"]?:@[@255,@255,@255];UIAlertController *alert=[UIAlertController alertControllerWithTitle:@"自定义弹幕颜色" message:@"RGB 每项为 0～255" preferredStyle:UIAlertControllerStyleAlert];for(NSUInteger index=0;index<3;index++)[alert addTextFieldWithConfigurationHandler:^(UITextField *field){field.placeholder=@[@"R",@"G",@"B"][index];field.text=[saved[index]description];field.keyboardType=UIKeyboardTypeNumberPad;}];[alert addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[alert addAction:[UIAlertAction actionWithTitle:@"应用" style:UIAlertActionStyleDefault handler:^(UIAlertAction *action){NSMutableArray *values=[NSMutableArray array];for(UITextField *field in alert.textFields){NSScanner *scanner=[NSScanner scannerWithString:field.text];NSInteger value;if(![scanner scanInteger:&value]||!scanner.isAtEnd||value<0||value>255){DGToast(self,@"请输入 0～255 的整数");return;}[values addObject:@(value)];}[NSUserDefaults.standardUserDefaults setObject:values forKey:@"douglass.danmaku.rgb"];[self notifyKey:@"douglass.danmaku.rgb"];}]];[self presentViewController:alert animated:YES completion:nil];}
- (void)tableView:(UITableView *)tableView didSelectRowAtIndexPath:(NSIndexPath *)path{
 [tableView deselectRowAtIndexPath:path animated:YES];NSDictionary *work=self.work;
 if(self.actions){NSInteger row=path.row;if(row==5){UIViewController *host=self.presentingViewController;DGSaveCurrentFrame(host);[self finish:nil];return;}[self finish:^(UIViewController *host){NSString *image=Text(String(work[@"selectedImage"]));if(!image.length)image=Text(String(Array(work[@"images"]).firstObject));if(row==0){NSString *url=image.length?image:Text(String(work[@"play"]));if(!url.length)DGToast(host,@"平台未提供可保存的媒体地址");else DGSaveURL(host,url,!image.length);}else if(row==1){NSString *url=Text(String(work[@"cover"]));if(url.length)DGSaveURL(host,url,NO);else DGToast(host,@"该作品没有封面地址");}else if(row==2)DGSaveAudioDirect(host,Text(String(work[@"music"])),Text(String(work[@"musicTitle"])));else if(row==3){NSString *caption=Text(String(work[@"caption"]));if(caption.length){UIPasteboard.generalPasteboard.string=caption;DGHaptic();DGToast(host,@"文案已复制");}else DGToast(host,@"该作品没有文案");}else{NSString *identifier=Text(String(work[@"id"]));if(!identifier.length){DGToast(host,@"没有可分享的作品标识");return;}UIPasteboard.generalPasteboard.string=[NSString stringWithFormat:@"https://www.douyin.com/%@/%@",image.length?@"note":@"video",identifier];DGHaptic();DGToast(host,@"分享链接已复制");}}];return;}
 NSDictionary *row=[self rows][path.section][path.row];NSString *action=row[@"action"];if([action isEqualToString:@"font"]){
  UIAlertController *chooser=[UIAlertController alertControllerWithTitle:@"字体替换" message:nil preferredStyle:UIAlertControllerStyleActionSheet];
  [chooser addAction:[UIAlertAction actionWithTitle:@"选择系统字体" style:UIAlertActionStyleDefault handler:^(UIAlertAction *action){UIFontPickerViewControllerConfiguration *configuration=[UIFontPickerViewControllerConfiguration new];configuration.includeFaces=YES;UIFontPickerViewController *picker=[[UIFontPickerViewController alloc]initWithConfiguration:configuration];picker.delegate=self;[self presentViewController:picker animated:YES completion:nil];}]];
  [chooser addAction:[UIAlertAction actionWithTitle:@"从文件导入" style:UIAlertActionStyleDefault handler:^(UIAlertAction *action){UIDocumentPickerViewController *picker=[[UIDocumentPickerViewController alloc]initForOpeningContentTypes:@[UTTypeFont] asCopy:YES];picker.delegate=self;[self presentViewController:picker animated:YES completion:nil];}]];
  [chooser addAction:[UIAlertAction actionWithTitle:@"恢复默认字体" style:UIAlertActionStyleDefault handler:^(UIAlertAction *action){NSUserDefaults *prefs=NSUserDefaults.standardUserDefaults;[prefs removeObjectForKey:@"douglass.danmaku.fontName"];[prefs removeObjectForKey:@"douglass.danmaku.font"];[self notifyKey:@"douglass.danmaku.fontName"];[self->_table reloadData];}]];
  [chooser addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];
  chooser.popoverPresentationController.sourceView=tableView;chooser.popoverPresentationController.sourceRect=[tableView rectForRowAtIndexPath:path];[self presentViewController:chooser animated:YES completion:nil];return;
 }

 if([action isEqualToString:@"logsView"]){[self finish:^(UIViewController *host){DGDiagnosticShow(host);}];return;}
 if([action isEqualToString:@"logsExport"]){[self finish:^(UIViewController *host){DGDiagnosticExport(host);}];return;}
 if([action isEqualToString:@"logsClear"]){DGDiagnosticClear(self);return;}
 if([action isEqualToString:@"rgb"])[self rgb];
 if([action isEqualToString:@"animation"]){[self finish:^(UIViewController *host){DGNavigationController *nav=[[DGNavigationController alloc]initWithRootViewController:DGMakeAnimationSettings()];DGConfigurePageTransition(nav);[host presentViewController:nav animated:YES completion:nil];}];}
 if([action isEqualToString:@"login"])[self finish:^(UIViewController *host){if([host respondsToSelector:@selector(openLogin)])[host performSelector:@selector(openLogin)];}];
 if([action isEqualToString:@"logout"]){DGBridge *bridge=self.bridge;[self finish:^(UIViewController *host){UIAlertController *alert=[UIAlertController alertControllerWithTitle:@"退出当前账号？" message:@"这会清除本机保存的当前登录信息" preferredStyle:UIAlertControllerStyleAlert];[alert addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[alert addAction:[UIAlertAction actionWithTitle:@"退出" style:UIAlertActionStyleDestructive handler:^(UIAlertAction *action){[bridge signOut:^{DGMusicStop();[NSNotificationCenter.defaultCenter postNotificationName:@"DGAccountChanged" object:nil];}];}]];[host presentViewController:alert animated:YES completion:nil];}];}
}
@end
static UIViewController *DGOptionsController(DGBridge *bridge,NSDictionary *work,BOOL actions){DGOptions *options=[DGOptions new];options.bridge=bridge;options.work=work?:@{};options.actions=actions;options.modalPresentationStyle=UIModalPresentationCustom;options.transitioningDelegate=options;return options;}
UIViewController *DGMakeOptions(DGBridge *bridge,NSDictionary *work){return DGOptionsController(bridge,work,NO);}
UIViewController *DGMakeActions(DGBridge *bridge,NSDictionary *work){return DGOptionsController(bridge,work,YES);}
BOOL DGOptionsKeepsPlayback(UIViewController *controller){return [controller isKindOfClass:DGOptions.class];}
